// Generates src/iso4217.ts from the ISO 4217 table shared with the Java engine
// (rulestone-api/src/main/resources/vn/io/dxa/rulestone/api/iso4217.txt).
// test/iso4217.test.ts fails if the generated file is out of date.

import { readFileSync, writeFileSync } from 'node:fs'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
export const SOURCE = join(root, '..', '..', '..', 'rulestone-api', 'src', 'main', 'resources', 'vn', 'io', 'dxa', 'rulestone', 'api', 'iso4217.txt')
export const TARGET = join(root, 'src', 'iso4217.ts')

/** The TypeScript module for the table text. */
export function generate(text) {
  let amendment
  const entries = []
  for (const raw of text.split('\n')) {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) continue
    const [key, value] = line.split(' ')
    if (key === 'amendment') amendment = Number(value)
    else entries.push(`${key}${value}`)
  }
  return `// Copyright 2026 The RuleStone Authors
// SPDX-License-Identifier: Apache-2.0

// GENERATED by scripts/generate-iso4217.mjs from the ISO 4217 table shared with the Java engine
// (rulestone-api/src/main/resources/vn/io/dxa/rulestone/api/iso4217.txt). Do not edit.

/** The ISO 4217 amendment the table reflects. */
export const ISO4217_AMENDMENT = ${amendment}

/** Each entry is a code followed by its minor units, or '-' for a code without one. */
export const ISO4217_ENTRIES = '${entries.join(' ')}'
`
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  writeFileSync(TARGET, generate(readFileSync(SOURCE, 'utf8')))
  console.log(`wrote ${TARGET}`)
}
